#pragma once
#include "Processor.h"
#include "GlassStyle.h"
#include "ArpMidi.h"
class ArpView final:public juce::Component,private juce::Timer {
 NovaProcessor& p;juce::ToggleButton enabled{"Activar arpegio"};std::unique_ptr<juce::FileChooser> chooser;juce::TextButton exportMidi{"Exportar MIDI"};juce::Slider exportRoot;int lastReferenceRoot=-1;juce::TextButton clear{"Limpiar"},close{"Cerrar"};juce::Slider bpm;juce::Colour accent;
 juce::Rectangle<float> grid()const{return {48,56,getWidth()-60.f,280};}
public:
 std::function<void()> onClose;
 void setAccent(juce::Colour c){accent=c;repaint();}
 ArpView(NovaProcessor& processor,juce::Colour colour):p(processor),accent(colour){setSize(900,410);addAndMakeVisible(exportMidi);addAndMakeVisible(exportRoot);exportRoot.setRange(24,108,1);exportRoot.setValue(p.v("root"),juce::dontSendNotification);exportRoot.setTextBoxStyle(juce::Slider::TextBoxRight,false,45,24);exportRoot.setTooltip("Nota MIDI base del archivo exportado. No cambia la nota de referencia del instrumento.");exportMidi.onClick=[this]{
    std::array<int,nova::arpSteps> pattern;bool any=false;for(int i=0;i<nova::arpSteps;++i){pattern[i]=p.arpNotes[i].load();any|=pattern[i]!=nova::arpRest;}if(!any){p.say("Crea al menos una nota antes de exportar MIDI.");return;}
    int root=static_cast<int>(exportRoot.getValue());float tempo=p.arpBpm.load();chooser=std::make_unique<juce::FileChooser>("Guardar arpegio MIDI",juce::File{},"*.mid");auto safe=juce::Component::SafePointer<ArpView>(this);chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[safe,pattern,root,tempo](const juce::FileChooser& c){if(!safe||c.getResult()==juce::File{})return;auto file=c.getResult().withFileExtension("mid");juce::MemoryOutputStream bytes;auto midi=nova::arpMidi(pattern,root,tempo);safe->p.say(midi.writeTo(bytes)&&file.replaceWithData(bytes.getData(),bytes.getDataSize())?"MIDI guardado. Arrastralo al piano roll de FL Studio.":"No se pudo guardar el MIDI.");});};addAndMakeVisible(enabled);addAndMakeVisible(clear);addAndMakeVisible(close);addAndMakeVisible(bpm);close.onClick=[this]{if(onClose)onClose();};enabled.setToggleState(p.arpEnabled.load(),juce::dontSendNotification);enabled.onClick=[this]{p.arpEnabled.store(enabled.getToggleState());};clear.onClick=[this]{p.resetArpPattern();repaint();};bpm.setRange(30,300,1);bpm.setValue(p.arpBpm.load(),juce::dontSendNotification);bpm.setTextBoxStyle(juce::Slider::TextBoxRight,false,60,24);bpm.onValueChange=[this]{p.arpBpm.store(static_cast<float>(bpm.getValue()));};startTimerHz(10);}
 void resized()override{enabled.setBounds(12,10,150,30);exportRoot.setBounds(628,10,130,30);exportMidi.setBounds(770,10,180,30);clear.setBounds(170,10,90,30);bpm.setBounds(310,10,250,30);close.setBounds(getWidth()-100,10,88,30);}
 void paint(juce::Graphics& g)override{g.setColour(juce::Colour(0xff080e18));g.fillRoundedRectangle(getLocalBounds().toFloat(),22);nova::glass::panel(g,getLocalBounds().toFloat(),accent,22,this);g.setColour(juce::Colours::white);g.setFont(13.f);g.drawText("MIDI base",566,10,62,30,juce::Justification::centred);g.drawText("BPM",270,10,38,30,juce::Justification::centred);auto area=grid();float w=area.getWidth()/16,h=area.getHeight()/49;for(int row=0;row<49;++row){int semitone=24-row;g.setColour(semitone==0?juce::Colour(0x28ffffff):juce::Colour(row%2?0x16080d18:0x08ffffff));g.fillRect(area.getX(),area.getY()+row*h,area.getWidth(),h);if(semitone%12==0){g.setColour(juce::Colour(0xffaaaaaa));g.drawText(juce::String(semitone),3,static_cast<int>(area.getY()+row*h-2),40,15,juce::Justification::centredRight);}}
  for(int step=0;step<16;++step){g.setColour(juce::Colour(0x30ffffff));g.drawVerticalLine(static_cast<int>(area.getX()+step*w),area.getY(),area.getBottom());int n=p.arpNotes[step].load();if(n>=-24&&n<=24){float x=area.getX()+step*w+2,y=area.getY()+(24-n)*h+1;nova::glass::halo(g,{x-5,y-7,w+6,h+12},accent,.28f);g.setColour(accent.brighter(.2f));g.fillRoundedRectangle(x,y,w-4,std::max(1.f,h-2),2);}}
  g.setColour(juce::Colour(0xffbbbbbb));g.drawText("Clic: crear/mover nota; clic en la misma nota: silencio. Mantiene una tecla para tocar. 16 pasos a corcheas dobles.",12,344,getWidth()-24,24,juce::Justification::centredLeft);g.drawText("Exporta un compas .mid con tempo, notas y silencios; arrastralo al piano roll para editar duraciones e intensidades.",12,370,getWidth()-24,24,juce::Justification::centredLeft);}
 void mouseDown(const juce::MouseEvent& e)override{auto area=grid();if(!area.contains(e.position))return;int step=std::clamp(static_cast<int>((e.position.x-area.getX())/area.getWidth()*16),0,15);int pitch=24-std::clamp(static_cast<int>((e.position.y-area.getY())/area.getHeight()*49),0,48);p.arpNotes[step].store(p.arpNotes[step].load()==pitch?nova::arpRest:pitch);repaint();}
 void timerCallback()override{int referenceRoot=static_cast<int>(p.v("root"));if(referenceRoot!=lastReferenceRoot&&!exportRoot.isMouseButtonDown()){lastReferenceRoot=referenceRoot;exportRoot.setValue(referenceRoot,juce::dontSendNotification);}enabled.setToggleState(p.arpEnabled.load(),juce::dontSendNotification);if(!bpm.isMouseButtonDown())bpm.setValue(p.arpBpm.load(),juce::dontSendNotification);}
};
